class Solution:
    def sumSubarrayMins(self, arr: List[int]) -> int:
        MOD = 10**9 + 7
        n = len(arr)
        left = [0] * n
        right = [0] * n
        st = []
        for i in range(n):
            while st and arr[st[-1]] > arr[i]:
                st.pop()
            left[i] = i + 1 if not st else i - st[-1]
            st.append(i)
        st = []
        for i in range(n - 1, -1, -1):
            while st and arr[st[-1]] >= arr[i]:
                st.pop()
            right[i] = n - i if not st else st[-1] - i
            st.append(i)
        return sum(arr[i] * left[i] * right[i] for i in range(n)) % MOD

class Solution {
public:
    int sumSubarrayMins(vector<int>& arr) {
        long long MOD = 1e9 + 7;
        int n = arr.size();
        vector<int> left(n), right(n);
        vector<int> st;
        for (int i = 0; i < n; i++) {
            while (!st.empty() && arr[st.back()] > arr[i]) st.pop_back();
            left[i] = st.empty() ? i + 1 : i - st.back();
            st.push_back(i);
        }
        st.clear();
        for (int i = n - 1; i >= 0; i--) {
            while (!st.empty() && arr[st.back()] >= arr[i]) st.pop_back();
            right[i] = st.empty() ? n - i : st.back() - i;
            st.push_back(i);
        }
        long long res = 0;
        for (int i = 0; i < n; i++) {
            res = (res + (long long)arr[i] * left[i] % MOD * right[i]) % MOD;
        }
        return res;
    }
};

class Solution {
    public int sumSubarrayMins(int[] arr) {
        long MOD = 1000000007L;
        int n = arr.length;
        int[] left = new int[n];
        int[] right = new int[n];
        int[] st = new int[n];
        int top = 0;
        for (int i = 0; i < n; i++) {
            while (top > 0 && arr[st[top - 1]] > arr[i]) top--;
            left[i] = (top == 0) ? i + 1 : i - st[top - 1];
            st[top++] = i;
        }
        top = 0;
        for (int i = n - 1; i >= 0; i--) {
            while (top > 0 && arr[st[top - 1]] >= arr[i]) top--;
            right[i] = (top == 0) ? n - i : st[top - 1] - i;
            st[top++] = i;
        }
        long res = 0;
        for (int i = 0; i < n; i++) {
            res = (res + (long)arr[i] * left[i] % MOD * right[i]) % MOD;
        }
        return (int)res;
    }
}

var sumSubarrayMins = function(arr) {
    const MOD = 1000000007;
    const n = arr.length;
    const left = new Array(n);
    const right = new Array(n);
    let st = [];
    for (let i = 0; i < n; i++) {
        while (st.length > 0 && arr[st[st.length - 1]] > arr[i]) st.pop();
        left[i] = st.length === 0 ? i + 1 : i - st[st.length - 1];
        st.push(i);
    }
    st = [];
    for (let i = n - 1; i >= 0; i--) {
        while (st.length > 0 && arr[st[st.length - 1]] >= arr[i]) st.pop();
        right[i] = st.length === 0 ? n - i : st[st.length - 1] - i;
        st.push(i);
    }
    let res = 0;
    for (let i = 0; i < n; i++) {
        const prod = (BigInt(arr[i]) * BigInt(left[i]) * BigInt(right[i])) % BigInt(MOD);
        res = (res + Number(prod)) % MOD;
    }
    return res;
};
